options.getOption:
const frame = (context.panel.data.series || [])[0];
function vals(f) { if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const tField = frame && frame.fields.find((f) => f.type === 'time' || f.name === 'ref_month');
const vField = frame && frame.fields.find((f) => f.name === 'nb_patients_controlled');
const tr = context.panel.data.timeRange;
const from = tr ? tr.from.valueOf() : -Infinity;
const to = tr ? tr.to.valueOf() : Infinity;
const pts = vals(tField).map((t, i) => [Number(t), Number(vals(vField)[i]) || 0])
  .filter((p) => p[0] >= from && p[0] <= to)
  .sort((a, b) => a[0] - b[0]);
const last = pts.length ? pts[pts.length - 1] : null;
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const mLabel = (ms) => { const d = new Date(ms); return months[d.getUTCMonth()] + ' ' + d.getUTCFullYear(); };
const muted = '#6e7f8d';
const green = '#73BF69';
return {
  animation: false,
  graphic: [
    { type: 'text', left: 4, top: 0, style: { text: last ? last[1].toLocaleString('en-US') + ' patients' : 'No data', fontSize: 30, fontWeight: 700, fill: green } },
    { type: 'text', left: 4, top: 40, style: { text: 'Patients with BP <140/90' + (last ? ' · ' + mLabel(last[0]) : ''), fontSize: 13, fill: muted } }
  ],
  grid: { left: 44, right: 16, top: 72, bottom: 26 },
  tooltip: { trigger: 'axis', valueFormatter: (v) => Number(v).toLocaleString('en-US') + ' patients' },
  xAxis: { type: 'time', axisLabel: { color: muted, fontSize: 11, hideOverlap: true, formatter: (v) => mLabel(v) }, axisLine: { lineStyle: { color: 'rgba(128,128,128,0.4)' } }, splitLine: { show: false } },
  yAxis: { type: 'value', min: 0, splitNumber: 3, axisLabel: { color: muted, fontSize: 11, formatter: (v) => v >= 1000 ? (v / 1000) + 'k' : v }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } },
  series: [{
    type: 'line', name: 'Patients with BP <140/90', data: pts, showSymbol: true, symbolSize: 5,
    lineStyle: { color: green, width: 2 }, itemStyle: { color: green },
    areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(115,191,105,0.35)' }, { offset: 1, color: 'rgba(115,191,105,0.02)' }] } },
    markPoint: last ? { symbol: 'circle', symbolSize: 9, itemStyle: { color: green }, label: { show: false }, data: [{ coord: last }] } : undefined
  }]
};

options.styles:
.stc { display: flex; gap: 0; height: 100%; font-size: 13px; line-height: 1.3; padding: 2px 4px; }
.stc-col { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; }
.stc-divider { width: 1px; background: rgba(128,128,128,0.25); margin: 4px 22px; }
.stc-head h3 { font-size: 17px; font-weight: 700; margin: 0 0 2px 0; }
.stc-den { color: #6e7f8d; font-size: 13px; }
.stc-tag { display: inline-block; margin-top: 4px; font-size: 11px; color: #6e7f8d; border: 1px solid rgba(128,128,128,0.3); border-radius: 10px; padding: 0 8px; }
.stc-tagline { display: flex; justify-content: space-between; align-items: flex-end; gap: 8px; margin-top: 4px; }
.stc-tagline .stc-tag { margin-top: 0; white-space: nowrap; }
.stc-ref { font-size: 11px; color: #6e7f8d; text-align: right; margin-right: 82px; white-space: nowrap; }
.stc-ref b { color: inherit; font-weight: 700; }
.stc-rows { display: flex; flex-direction: column; gap: 12px; margin-top: 14px; }
.stc-row { display: grid; grid-template-columns: 112px 1fr 70px; align-items: center; column-gap: 12px; }
.stc-row-target { padding-bottom: 18px; }
.stc-label { font-size: 13px; }
.stc-caption { grid-column: 1 / -1; font-size: 11px; color: #6e7f8d; margin-top: 3px; }
.stc-track { position: relative; height: 22px; background: rgba(128,128,128,0.14); border-radius: 2px; }
.stc-treatment .stc-track { border-right: 2px dashed #8a9599; }
.stc-bar { height: 100%; border-radius: 2px; }
.stc-eligible { background: #c3ccd2; }
.stc-screened { background: #FF9830; }
.stc-suspected { background: #F2495C; }
.stc-registered { background: #5794F2; }
.stc-undercare { background: #B877D9; }
.stc-controlled { background: #73BF69; }
.stc-target { position: absolute; top: -6px; bottom: -6px; border-left: 2px dashed #FA6400; transform: translateX(-1px); }
.stc-target-label { position: absolute; top: 28px; transform: translateX(-50%); white-space: nowrap; color: #FA6400; font-size: 12px; font-weight: 600; }
.stc-pct { font-size: 17px; font-weight: 700; }
.stc-cnt { font-size: 13px; color: #6e7f8d; }
